// Asserts that a word exists in the trie
void helper_assert_trie_contains(struct trie *trie, const char *word) {
    int result = trie_contains(trie, (char*)word, strlen(word));
    TEST_ASSERT_EQUAL_INT(1, result);
}

// Asserts that a word does not exist in the trie
void helper_assert_trie_not_contains(struct trie *trie, const char *word) {
    int result = trie_contains(trie, (char*)word, strlen(word));
    TEST_ASSERT_EQUAL_INT(0, result);
}

// Asserts that the trie contains a specific number of words
void helper_assert_trie_word_count(struct trie *trie, int expected_count) {
    int actual_count = trie_count_words(trie);
    TEST_ASSERT_EQUAL_INT(expected_count, actual_count);
}

// Asserts that the trie contains a specific number of nodes
void helper_assert_trie_node_count(struct trie *trie, int expected_count) {
    int actual_count = trie_count_nodes(trie);
    TEST_ASSERT_EQUAL_INT(expected_count, actual_count);
}

// Asserts that the trie is empty (contains no words)
void helper_assert_trie_empty(struct trie *trie) {
    int result = trie_is_empty(trie);
    TEST_ASSERT_EQUAL_INT(1, result);
}

// Asserts that the trie is not empty (contains at least one word)
void helper_assert_trie_not_empty(struct trie *trie) {
    int result = trie_is_empty(trie);
    TEST_ASSERT_EQUAL_INT(0, result);
}

// Asserts that a trie node is a leaf (has no children)
void helper_assert_trie_leaf(struct trie *trie) {
    int result = trie_is_leaf(trie);
    TEST_ASSERT_EQUAL_INT(1, result);
}

// Asserts that a trie node is not a leaf (has at least one child)
void helper_assert_trie_not_leaf(struct trie *trie) {
    int result = trie_is_leaf(trie);
    TEST_ASSERT_EQUAL_INT(0, result);
}

// Asserts that a trie node has a specific number of children
void helper_assert_trie_child_count(struct trie *trie, int expected_count) {
    int actual_count = trie_get_child_count(trie);
    TEST_ASSERT_EQUAL_INT(expected_count, actual_count);
}

// Asserts that a prefix node exists in the trie and returns a non-null result
void helper_assert_trie_prefix_node(struct trie *trie, const char *prefix) {
    struct trie *result = NULL;
    int ret = trie_get_prefix_node(trie, (char*)prefix, &result);
    TEST_ASSERT_EQUAL_INT(0, ret);
    TEST_ASSERT_NOT_NULL(result);
}

// Asserts that collected words from trie match expected words
void helper_assert_trie_collect_words(struct trie *trie, const char *prefix, const char **expected_words, int expected_count) {
    char **buffer = malloc(expected_count * sizeof(char *));
    int collected_count = trie_collect_words(trie, (char*)prefix, buffer, expected_count);
    TEST_ASSERT_EQUAL_INT(expected_count, collected_count);
    for (int i = 0; i < expected_count; i++) {
        TEST_ASSERT_EQUAL_STRING(expected_words[i], buffer[i]);
    }
    for (int i = 0; i < collected_count; i++) {
        free(buffer[i]);
    }
    free(buffer);
}

// Asserts that all words in an array exist in the trie
void helper_assert_trie_contains_all(struct trie *trie, const char **words, int word_count) {
    int result = trie_contains_all(trie, words, word_count);
    TEST_ASSERT_EQUAL_INT(1, result);
}

// Asserts that a specific number of words were inserted from an array
void helper_assert_trie_insert_words(struct trie *trie, const char **words, int word_count, int expected_inserted) {
    int inserted = trie_insert_words(trie, words, word_count);
    TEST_ASSERT_EQUAL_INT(expected_inserted, inserted);
}

// Asserts that trie_search returns a specific result code and sets result pointer appropriately
void helper_assert_trie_search_result(struct trie *trie, char *word, unsigned int word_len, int expected_ret, int expected_result_null) {
    struct trie *result = NULL;
    int ret = trie_search(trie, word, word_len, &result);
    TEST_ASSERT_EQUAL_INT(expected_ret, ret);
    if (expected_result_null) {
        TEST_ASSERT_NULL(result);
    } else {
        TEST_ASSERT_NOT_NULL(result);
    }
}

// Asserts that trie_insert returns a specific result code
void helper_assert_trie_insert_result(struct trie *trie, char *word, unsigned int word_len, int expected_ret) {
    int ret = trie_insert(trie, word, word_len);
    TEST_ASSERT_EQUAL_INT(expected_ret, ret);
}

// Asserts that trie_new returns a specific result code and allocates a non-null trie
void helper_assert_trie_new_result(int expected_ret) {
    struct trie *trie = NULL;
    int ret = trie_new(&trie);
    TEST_ASSERT_EQUAL_INT(expected_ret, ret);
    if (expected_ret == 0) {
        TEST_ASSERT_NOT_NULL(trie);
        free(trie);
    } else {
        TEST_ASSERT_NULL(trie);
    }
}

// Asserts that trie_print outputs exactly the expected string
void helper_assert_stdout_equals_trie_print(struct trie *trie, char *prefix, unsigned int prefix_len, const char *expected_output) {
    stdout_capture_t *cap = capture_stdout_start();
    trie_print(trie, prefix, prefix_len);
    assert_stdout_equals(cap, expected_output);
}

// Asserts that trie_print output contains a specific substring
void helper_assert_stdout_contains_trie_print(struct trie *trie, char *prefix, unsigned int prefix_len, const char *expected_substring) {
    stdout_capture_t *cap = capture_stdout_start();
    trie_print(trie, prefix, prefix_len);
    assert_stdout_contains(cap, expected_substring);
}

// Asserts that trie_print produces non-empty output
void helper_assert_stdout_not_empty_trie_print(struct trie *trie, char *prefix, unsigned prefix_len) {
    stdout_capture_t *cap = capture_stdout_start();
    trie_print(trie, prefix, prefix_len);
    assert_stdout_not_empty(cap);
}

// ========== Created - Utility Operations ==========

// Builds a trie from an array of words
struct trie* helper_build_trie(const char **words, int word_count) {
    struct trie *root = NULL;
    if (trie_new(&root) != 0) {
        return NULL;
    }
    for (int i = 0; i < word_count; i++) {
        // Use trie_insert instead of trie_insert_string
        trie_insert(root, (char*)words[i], strlen(words[i]));
    }
    return root;
}

